INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),51,15,'إن الذين اتقوا الله في جنات عظيمة، وعيون ماء جارية، أعطاهم الله جميع مُناهم من أصناف النعيم، فأخذوا ذلك راضين به، فَرِحة به نفوسهم، إنهم كانوا قبل ذلك النعيم محسنين في الدنيا بأعمالهم الصالحة.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/51/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=51) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
