INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),52,19,'كلوا طعامًا هنيئًا، واشربوا شرابًا سائغًا؛ جزاء بما عملتم من أعمال صالحة في الدنيا. وهم متكئون على سرر متقابلة، وزوَّجناهم بنساء بيض واسعات العيون حسانهنَّ.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/52/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=52) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),52,20,'كلوا طعامًا هنيئًا، واشربوا شرابًا سائغًا؛ جزاء بما عملتم من أعمال صالحة في الدنيا. وهم متكئون على سرر متقابلة، وزوَّجناهم بنساء بيض واسعات العيون حسانهنَّ.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/52/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=52) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),52,21,'والذين آمنوا واتبعتهم ذريتهم في الإيمان، وألحقنا بهم ذريتهم في منزلتهم في الجنة، وإن لم يبلغوا عمل آبائهم؛ لتَقَرَّ أعين الآباء بالأبناء عندهم في منازلهم، فيُجْمَع بينهم على أحسن الأحوال، وما نقصناهم شيئًا من ثواب أعمالهم. كل إنسان مرهون بعمله، لا يحمل ذنب غيره من الناس.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/52/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=52) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),52,22,'وزدناهم على ما ذُكر من النعيم فواكه ولحومًا مما يستطاب ويُشتهى، ومن هذا النعيم أنهم يتعاطَوْن في الجنة كأسًا من الخمر، يناول أحدهم صاحبه؛ ليتم بذلك سرورهم، وهذا الشراب مخالف لخمر الدنيا، فلا يزول به عقل صاحبه، ولا يحصل بسببه لغو، ولا كلام فيه إثم أو معصية.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/52/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=52) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),52,23,'وزدناهم على ما ذُكر من النعيم فواكه ولحومًا مما يستطاب ويُشتهى، ومن هذا النعيم أنهم يتعاطَوْن في الجنة كأسًا من الخمر، يناول أحدهم صاحبه؛ ليتم بذلك سرورهم، وهذا الشراب مخالف لخمر الدنيا، فلا يزول به عقل صاحبه، ولا يحصل بسببه لغو، ولا كلام فيه إثم أو معصية.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/52/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=52) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),52,24,'ويطوف عليهم غلمان مُعَدُّون لخدمتهم، كأنهم في الصفاء والبياض والتناسق لؤلؤ مصون في أصدافه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/52/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=52) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),52,25,'وأقبل أهل الجنة، يسأل بعضهم بعضًا عن عظيم ما هم فيه وسببه، قالوا: إنا كنا قبل في الدنيا- ونحن بين أهلينا- خائفين ربنا، مشفقين من عذابه وعقابه يوم القيامة. فمنَّ الله علينا بالهداية والتوفيق، ووقانا عذاب سموم جهنم، وهو نارها وحرارتها. إنا كنا من قبلُ نضرع إليه وحده لا نشرك معه غيره أن يقينا عذاب السَّموم ويوصلنا إلى النعيم، فاستجاب لنا وأعطانا سؤالنا، إنه هو البَرُّ الرحيم. فمن بِره ورحمته إيانا أنالنا رضاه والجنة، ووقانا مِن سخطه والنار.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/52/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=52) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
