INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),53,5,'علَّم محمدًا صلى الله عليه وسلم مَلَك شديد القوة، ذو منظر حسن، وهو جبريل عليه السلام، الذي ظهر واستوى على صورته الحقيقية للرسول صلى الله عليه وسلم في الأفق الأعلى، وهو أفق الشمس عند مطلعها، ثم دنا جبريل من الرسول صلى الله عليه وسلم، فزاد في القرب، فكان دنوُّه مقدار قوسين أو أقرب من ذلك. فأوحى الله سبحانه وتعالى إلى عبده محمد صلى الله عليه وسلم ما أوحى بواسطة جبريل عليه السلام. ما كذب قلب محمد صلى الله عليه وسلم ما رآه بصره.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/53/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=53) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
