INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),53,19,'أفرأيتم- أيها المشركون- هذه الآلهة التي تعبدونها: اللات والعزَّى ومناة الثالثة الأخرى، هل نفعت أو ضرَّت حتى تكون شركاء لله؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/53/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=53) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
