INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),54,13,'وحملنا نوحًا ومَن معه على سفينة ذات ألواح ومسامير شُدَّت بها، تجري بمرأى منا وحفظ، وأغرقنا المكذبين؛ جزاء لهم على كفرهم وانتصارًا لنوح عليه السلام. وفي هذا دليل على إثبات صفة العينين لله سبحانه وتعالى، كما يليق به.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/54/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=54) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),54,14,'وحملنا نوحًا ومَن معه على سفينة ذات ألواح ومسامير شُدَّت بها، تجري بمرأى منا وحفظ، وأغرقنا المكذبين؛ جزاء لهم على كفرهم وانتصارًا لنوح عليه السلام. وفي هذا دليل على إثبات صفة العينين لله سبحانه وتعالى، كما يليق به.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/54/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=54) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),54,15,'ولقد أبقينا قصة نوح مع قومه عبرة ودليلا على قدرتنا لمن بعد نوح؛ ليعتبروا ويتعظوا بما حلَّ بهذه الأمة التي كفرت بربها، فهل من متعظ يتعظ؟ فكيف كان عذابي ونذري لمن كفر بي وكذب رسلي، ولم يتعظ بما جاءت به؟ إنه كان عظيمًا مؤلمًا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/54/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=54) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),54,16,'ولقد أبقينا قصة نوح مع قومه عبرة ودليلا على قدرتنا لمن بعد نوح؛ ليعتبروا ويتعظوا بما حلَّ بهذه الأمة التي كفرت بربها، فهل من متعظ يتعظ؟ فكيف كان عذابي ونذري لمن كفر بي وكذب رسلي، ولم يتعظ بما جاءت به؟ إنه كان عظيمًا مؤلمًا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/54/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=54) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),54,17,'ولقد سَهَّلْنا لفظ القرآن للتلاوة والحفظ، ومعانيه للفهم والتدبر، لمن أراد أن يتذكر ويعتبر، فهل من متعظ به؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/54/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=54) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),54,18,'كذبت عاد هودًا فعاقبناهم، فكيف كان عذابي لهم على كفرهم، ونذري على تكذيب رسولهم، وعدم الإيمان به؟ إنه كان عظيمًا مؤلمًا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/54/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=54) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),54,19,'إنَّا أرسلنا عليهم ريحًا شديدة البرد، في يوم شؤم مستمر عليهم بالعذاب والهلاك، تقتلع الناس من مواضعهم على الأرض فترمي بهم على رؤوسهم، فتدق أعناقهم، ويفصل رؤوسهم عن أجسادهم، فتتركهم كالنخل المنقلع من أصله.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/54/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=54) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),54,20,'إنَّا أرسلنا عليهم ريحًا شديدة البرد، في يوم شؤم مستمر عليهم بالعذاب والهلاك، تقتلع الناس من مواضعهم على الأرض فترمي بهم على رؤوسهم، فتدق أعناقهم، ويفصل رؤوسهم عن أجسادهم، فتتركهم كالنخل المنقلع من أصله.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/54/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=54) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),54,21,'فكيف كان عذابي ونذري لمن كفر بي، وكذَّب رسلي ولم يؤمن بهم؟ إنه كان عظيمًا مؤلمًا.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/54/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=54) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),54,22,'ولقد سَهَّلنا لفظ القرآن للتلاوة والحفظ، ومعانيه للفهم وللتدبر، لمن أراد أن يتذكر ويعتبر، فهل من متعظ به؟ وفي هذا حثٌّ على الاستكثار من تلاوة القرآن وتعلمه وتعليمه.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/54/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=54) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),54,23,'كذبت ثمود -وهم قوم صالح- بالآيات التي أُنذرِوا بها، فقالوا: أبشرًا منا واحدًا نتبعه نحن الجماعة الكثيرة وهو واحد؟ إنا إذا لفي بُعْدٍ عن الصواب وجنون.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/54/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=54) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),54,24,'كذبت ثمود -وهم قوم صالح- بالآيات التي أُنذرِوا بها، فقالوا: أبشرًا منا واحدًا نتبعه نحن الجماعة الكثيرة وهو واحد؟ إنا إذا لفي بُعْدٍ عن الصواب وجنون.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/54/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=54) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),54,25,'أأُنزل عليه الوحي وخُصَّ بالنبوة مِن بيننا، وهو واحد منا؟ بل هو كثير الكذب والتجبر. سَيَرون عند نزول العذاب بهم في الدنيا ويوم القيامة مَنِ الكذاب المتجبر؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/54/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=54) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),54,26,'أأُنزل عليه الوحي وخُصَّ بالنبوة مِن بيننا، وهو واحد منا؟ بل هو كثير الكذب والتجبر. سَيَرون عند نزول العذاب بهم في الدنيا ويوم القيامة مَنِ الكذاب المتجبر؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/54/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=54) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),54,27,'إنا مخرجو الناقة التي سألوها من الصخرة؛ اختبارًا لهم، فانتظر- يا صالح- ما يحلُّ بهم من العذاب، واصطبر على دعوتك إياهم وأذاهم لك.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/54/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=54) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),54,28,'وأخبرهم أن الماء مقسوم بين قومك والناقة: للناقة يوم، ولهم يوم، كل شِرْب يحضره مَن كانت قسمته، ويُحظر على من ليس بقسمة له.','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/54/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=54) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
INSERT INTO public.quran_tafsir (id,surah_id,ayah_number,tafsir_ar,author,created_at,updated_at,source_url,retrieved_at) SELECT gen_random_uuid(),54,29,'فنادوا صاحبهم بالحض على عقرها، فتناول الناقة بيده، فنحرها فعاقَبْتُهم، فكيف كان عقابي لهم على كفرهم، وإنذاري لمن عصى رسلي؟','التفسير الميسر',now(),now(),'https://api.alquran.cloud/v1/surah/54/ar.muyassar','2026-08-17T00:00:00+00:00' WHERE EXISTS (SELECT 1 FROM public.quran_surahs WHERE id=54) ON CONFLICT (surah_id,ayah_number,author) DO UPDATE SET tafsir_ar=excluded.tafsir_ar,updated_at=now(),source_url=excluded.source_url,retrieved_at=excluded.retrieved_at;
